sp_widget.client_script:
api.controller = function($timeout,$location) {

    var c = this;

    c.filters = {};

    c.loading = false;
    c.refreshing = false;

    c.sortDescending = true;

    c.successMessage = "";
    c.errorMessage = "";

    c.requestSearch = "";
    c.showRequestDropdown = false;

    c.filteredRequestNumbers = [];
    c.activeRequestIndex = -1;

    c.displayRecords = angular.copy(
        c.data.records || []
    );


    initializeRequestNumbers();


    function initializeRequestNumbers() {

        var requestNumbers = [];

        if (
            c.data.filterOptions &&
            c.data.filterOptions.requestNumbers
        ) {
            requestNumbers =
                c.data.filterOptions.requestNumbers;
        }

        c.filteredRequestNumbers =
            angular.copy(requestNumbers);
    }


    function updateDisplayRecords(records) {

        var updatedRecords = records || [];

        c.data.records = updatedRecords;

        c.displayRecords =
            updatedRecords.slice(0);

        if (!c.sortDescending) {
            c.displayRecords.reverse();
        }
    }


    function clearMessages() {

        c.successMessage = "";
        c.errorMessage = "";
    }


    /*
     * Filter the request-number dropdown
     * using the text entered by the user.
     */
    c.filterRequestNumbers = function() {

        var searchValue = String(
            c.requestSearch || ""
        )
            .trim()
            .toLowerCase();

        var requestNumbers =
            c.data.filterOptions &&
            c.data.filterOptions.requestNumbers
                ? c.data.filterOptions.requestNumbers
                : [];

        c.filters.requestNumber = String(
            c.requestSearch || ""
        ).trim();

        if (!searchValue) {

            c.filteredRequestNumbers =
                angular.copy(requestNumbers);

        } else {

            c.filteredRequestNumbers =
                requestNumbers.filter(
                    function(number) {

                        return String(number)
                            .toLowerCase()
                            .indexOf(searchValue) !== -1;
                    }
                );
        }

        c.activeRequestIndex = -1;
        c.showRequestDropdown = true;
    };


    c.openRequestDropdown = function() {

        c.filterRequestNumbers();
        c.showRequestDropdown = true;
    };


    c.toggleRequestDropdown = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.showRequestDropdown =
            !c.showRequestDropdown;

        if (c.showRequestDropdown) {
            c.filterRequestNumbers();
        }
    };


    c.hideRequestDropdown = function() {

        $timeout(function() {

            c.showRequestDropdown = false;
            c.activeRequestIndex = -1;

        }, 200);
    };


    c.selectRequestNumber = function(
        requestNumber,
        event
    ) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.requestSearch =
            requestNumber || "";

        c.filters.requestNumber =
            requestNumber || "";

        c.showRequestDropdown = false;
        c.activeRequestIndex = -1;
    };


    c.clearRequestNumber = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.requestSearch = "";
        c.filters.requestNumber = "";

        c.activeRequestIndex = -1;

        initializeRequestNumbers();

        c.showRequestDropdown = true;
    };


    c.handleRequestKeydown = function(event) {

        if (!event) {
            return;
        }

        var keyCode =
            event.which ||
            event.keyCode;

        var options =
            c.filteredRequestNumbers || [];


        // Down Arrow
        if (keyCode === 40) {

            event.preventDefault();

            c.showRequestDropdown = true;

            if (!options.length) {
                return;
            }

            c.activeRequestIndex++;

            if (
                c.activeRequestIndex >=
                options.length
            ) {
                c.activeRequestIndex = 0;
            }

            return;
        }


        // Up Arrow
        if (keyCode === 38) {

            event.preventDefault();

            if (!options.length) {
                return;
            }

            c.activeRequestIndex--;

            if (c.activeRequestIndex < 0) {
                c.activeRequestIndex =
                    options.length - 1;
            }

            return;
        }


        // Enter
        if (keyCode === 13) {

            event.preventDefault();

            if (
                c.showRequestDropdown &&
                c.activeRequestIndex >= 0 &&
                options[c.activeRequestIndex]
            ) {

                c.selectRequestNumber(
                    options[
                        c.activeRequestIndex
                    ]
                );
            }

            c.search();

            return;
        }


        // Escape
        if (keyCode === 27) {

            c.showRequestDropdown = false;
            c.activeRequestIndex = -1;
        }
    };


    /*
     * View is available for every status.
     */
    c.openView = function(record) {

        if (
            !record ||
            !record.sys_id
        ) {
            c.errorMessage =
                "Unable to open the selected record.";

            return;
        }

        $location.url(
            "?id=view_record_asean" +
            "&sys_id=" +
            encodeURIComponent(
                record.sys_id
            )
        );
    };


    c.goBack = function() {

        $location.url(
            "?id=employee_role_asean"
        );
    };


    c.search = function() {

        if (
            c.loading ||
            c.refreshing
        ) {
            return;
        }

        clearMessages();

        c.filters.requestNumber =
            String(
                c.requestSearch || ""
            ).trim();

        c.showRequestDropdown = false;
        c.loading = true;

        c.server.get({

            action: "search",
            filters: angular.copy(
                c.filters
            )

        }).then(

            function(response) {

                c.loading = false;

                updateDisplayRecords(
                    response.data.records || []
                );

                if (
                    response.data.success === false &&
                    response.data.message
                ) {
                    c.errorMessage =
                        response.data.message;
                }
            },

            function() {

                c.loading = false;

                c.errorMessage =
                    "Unable to search the " +
                    "learning applications.";
            }
        );
    };


    c.reset = function() {

        if (
            c.loading ||
            c.refreshing
        ) {
            return;
        }

        clearMessages();

        c.filters = {};
        c.requestSearch = "";

        c.showRequestDropdown = false;
        c.activeRequestIndex = -1;

        c.sortDescending = true;
        c.loading = true;

        c.server.get({

            action: "reset",
            filters: {}

        }).then(

            function(response) {

                c.loading = false;

                updateDisplayRecords(
                    response.data.records || []
                );

                if (
                    response.data.filterOptions
                ) {

                    c.data.filterOptions =
                        response.data.filterOptions;
                }

                initializeRequestNumbers();

                if (
                    response.data.success === false &&
                    response.data.message
                ) {
                    c.errorMessage =
                        response.data.message;
                }
            },

            function() {

                c.loading = false;

                c.errorMessage =
                    "Unable to reset the " +
                    "learning applications.";
            }
        );
    };


    c.refresh = function() {

        if (
            c.refreshing ||
            c.loading
        ) {
            return;
        }

        clearMessages();

        c.filters.requestNumber =
            String(
                c.requestSearch || ""
            ).trim();

        c.showRequestDropdown = false;
        c.refreshing = true;


        var refreshTimeout =
            $timeout(function() {

                if (c.refreshing) {

                    c.refreshing = false;

                    c.errorMessage =
                        "Refresh took too long. " +
                        "Please try again.";
                }

            }, 15000);


        c.server.get({

            action: "refresh",
            filters: angular.copy(
                c.filters
            )

        }).then(

            function(response) {

                $timeout.cancel(
                    refreshTimeout
                );

                c.refreshing = false;

                updateDisplayRecords(
                    response.data.records || []
                );

                if (
                    response.data.filterOptions
                ) {

                    c.data.filterOptions =
                        response.data.filterOptions;

                    initializeRequestNumbers();
                }

                if (
                    response.data.success === false &&
                    response.data.message
                ) {
                    c.errorMessage =
                        response.data.message;
                }
            },

            function() {

                $timeout.cancel(
                    refreshTimeout
                );

                c.refreshing = false;

                c.errorMessage =
                    "Unable to refresh the " +
                    "learning applications.";
            }
        );
    };


    c.toggleSort = function() {

        if (
            c.loading ||
            c.refreshing
        ) {
            return;
        }

        c.sortDescending =
            !c.sortDescending;

        c.displayRecords.reverse();
    };


    c.getStatusClass = function(
        statusValue
    ) {

        switch (statusValue) {

            case "draft":
                return "status-draft";


            case "submitted":
                return "status-submitted";


            case "pending_manager_approval":
            case "pending_l2_approval":
            case "pending_hr_review":
            case "return_by_manager":
            case "return_by_l2":
            case "return_by_hr":
                return "status-approval";


            case "approved":
                return "status-approved";


            case "learning_in_progress":
                return "status-progress";


            case "pending_feedback":
                return "status-feedback";


            case "completed":
                return "status-complete";


            case "rejected":
                return "status-rejected";


            default:
                return "status-default";
        }
    };

};

sp_widget.css:
.learning-records-page {
    position: relative;
    width: 100%;
    min-height: 610px;
    overflow: visible;
    background: #ffffff;
    border: 1px solid #555555;
    font-family: Arial, Helvetica, sans-serif;
}


/* =====================================================
   Header
   ===================================================== */

.records-page-header {
    display: flex;
    min-height: 84px;
    padding: 12px 20px;
    align-items: flex-start;
    background: #ffffff;
    border-bottom: 1px solid #dddddd;
}

.records-title {
    flex: 1;
    color: #ed6b21;
    font-size: 28px;
    font-weight: 500;
    line-height: 55px;
}

.logged-in-user-details {
    width: 390px;
    padding-top: 4px;
    margin-right: 20px;
}

.user-detail-row {
    display: flex;
    margin-bottom: 8px;
    align-items: center;
}

.user-detail-label {
    width: 95px;
    color: #666666;
    font-size: 12px;
}

.user-detail-value {
    color: #222222;
    font-size: 15px;
    text-decoration: underline;
}

.healthineers-logo {
    position: relative;
    min-width: 165px;
    padding-right: 30px;
    text-align: right;
}

.siemens-text {
    color: #009999;
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 1px;
}

.healthineers-text {
    color: #ed6b21;
    font-size: 18px;
    font-weight: 700;
}

.healthineers-dots {
    position: absolute;
    top: 5px;
    right: 0;
    width: 23px;
}

.healthineers-dots span {
    display: block;
    width: 7px;
    height: 7px;
    margin: 2px auto;
    background: #ed6b21;
    border-radius: 50%;
}


/* =====================================================
   Messages
   ===================================================== */

.main-message {
    margin: 12px 18px;
}


/* =====================================================
   Filter Section
   ===================================================== */

.records-filter-section {
    position: relative;
    z-index: 30;
    padding: 18px 30px 20px;
    overflow: visible;
    background: #eeeeee;
    border-bottom: 1px solid #d4d4d4;
}

.filter-section-title {
    padding-bottom: 12px;
    margin-bottom: 15px;
    color: #444444;
    border-bottom: 1px solid #d2d2d2;
    font-size: 17px;
    font-weight: 600;
}

.filter-section-title i {
    margin-right: 7px;
    color: #ed6b21;
}

.filter-fields-container {
    display: grid;
    max-width: 1100px;
    margin: 0 auto;
    overflow: visible;
    grid-template-columns: repeat(
        2,
        minmax(320px, 1fr)
    );
    column-gap: 40px;
    row-gap: 15px;
}

.filter-item {
    position: relative;
    display: flex;
    min-width: 0;
    overflow: visible;
    align-items: center;
}

.filter-item label {
    width: 160px;
    margin: 0 12px 0 0;
    color: #444444;
    font-size: 14px;
    font-weight: 600;
    text-align: right;
}

.filter-control {
    flex: 1;
    height: 38px;
    min-width: 0;
    padding: 5px 30px 5px 10px;
    color: #333333;
    background: #ffffff;
    border: 1px solid #bdbdbd;
    border-radius: 2px;
    box-shadow: none;
}


/* =====================================================
   Request Number Typeahead
   ===================================================== */

.request-filter-item {
    z-index: 50;
}

.request-filter-container {
    position: relative;
    flex: 1;
    min-width: 0;
    overflow: visible;
}

.request-input-wrapper {
    position: relative;
    width: 100%;
}

.request-number-input {
    width: 100%;
    padding-right: 64px;
}

.request-dropdown-button {
    position: absolute;
    top: 1px;
    right: 1px;
    width: 34px;
    height: 36px;
    padding: 0;
    color: #555555;
    background: transparent;
    border: 0;
    cursor: pointer;
}

.request-dropdown-button:hover {
    color: #ed6b21;
    background: #f7f7f7;
}

.request-clear-button {
    position: absolute;
    top: 1px;
    right: 35px;
    width: 28px;
    height: 36px;
    padding: 0;
    color: #888888;
    background: transparent;
    border: 0;
    cursor: pointer;
}

.request-clear-button:hover {
    color: #d9534f;
}

.request-dropdown {
    position: absolute;
    z-index: 9999;
    top: calc(100% + 2px);
    right: 0;
    left: 0;
    max-height: 230px;
    padding: 0;
    margin: 0;
    overflow-x: hidden;
    overflow-y: auto;
    background: #ffffff;
    border: 1px solid #aaaaaa;
    border-radius: 2px;
    box-shadow: 0 5px 14px rgba(0, 0, 0, 0.18);
    list-style: none;
}

.request-dropdown li {
    padding: 10px 12px;
    color: #333333;
    background: #ffffff;
    border-bottom: 1px solid #eeeeee;
    font-size: 13px;
    cursor: pointer;
}

.request-dropdown li:last-child {
    border-bottom: 0;
}

.request-dropdown li i {
    margin-right: 7px;
    color: #ed6b21;
}

.request-dropdown li:hover,
.request-dropdown .request-option-active {
    color: #222222;
    background: #fff2e9;
}

.request-dropdown .request-dropdown-all {
    color: #444444;
    font-weight: 600;
}

.request-dropdown .request-dropdown-empty {
    color: #777777;
    background: #fafafa;
    font-style: italic;
    text-align: center;
    cursor: default;
}

.request-dropdown .request-dropdown-empty:hover {
    background: #fafafa;
}


/* =====================================================
   Filter Buttons
   ===================================================== */

.filter-buttons-row {
    display: flex;
    margin-top: 22px;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 12px;
}

.filter-action-button {
    display: inline-flex;
    min-width: 125px;
    height: 40px;
    padding: 0 18px;
    align-items: center;
    justify-content: center;
    color: #ffffff;
    border: 1px solid transparent;
    border-radius: 3px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
}

.filter-action-button i {
    margin-right: 7px;
}

.filter-action-button[disabled] {
    cursor: not-allowed;
    opacity: 0.6;
}

.primary-filter-button {
    background: #40ae58;
    border-color: #359a4a;
}

.primary-filter-button:hover {
    background: #359a4a;
}

.reset-filter-button {
    color: #444444;
    background: #ffffff;
    border-color: #aaaaaa;
}

.reset-filter-button:hover {
    background: #f5f5f5;
}

.secondary-filter-button {
    background: #687783;
    border-color: #586771;
}

.secondary-filter-button:hover {
    background: #586771;
}

.refresh-filter-button {
    background: #168b99;
    border-color: #117682;
}

.refresh-filter-button:hover {
    background: #117682;
}


/* =====================================================
   Loading and Empty State
   ===================================================== */

.records-loading,
.records-empty-message {
    padding: 45px 20px;
    color: #666666;
    font-size: 15px;
    text-align: center;
}

.records-loading div {
    margin-top: 10px;
}


/* =====================================================
   Records Table
   ===================================================== */

.records-table-wrapper {
    position: relative;
    z-index: 1;
    width: 100%;
    max-height: 500px;
    overflow-x: auto;
    overflow-y: auto;
    background: #ffffff;
}

.records-table {
    width: 100%;
    min-width: 4250px;
    table-layout: fixed;
    border-collapse: separate;
    border-spacing: 0;
}

.records-table thead th {
    position: sticky;
    z-index: 5;
    top: 0;
    width: 155px;
    min-width: 155px;
    max-width: 155px;
    padding: 10px 12px;
    color: #ffffff;
    background: #959595;
    border-right: 1px solid #b7b7b7;
    border-bottom: 1px solid #777777;
    font-size: 14px;
    font-weight: 700;
    text-align: center;
    vertical-align: middle;
}

.records-table tbody td {
    width: 155px;
    min-width: 155px;
    max-width: 155px;
    padding: 12px 13px;
    color: #4c4c4c;
    background: #ffffff;
    border-right: 1px solid #eeeeee;
    border-bottom: 2px solid #d5e9f4;
    font-size: 13px;
    text-align: center;
    vertical-align: top;
    word-break: break-word;
}

.records-table tbody tr:hover td {
    background: #fafafa;
}


/* =====================================================
   Sticky Columns
   ===================================================== */

.request-header {
    position: sticky !important;
    z-index: 12 !important;
    left: 0;
    width: 175px !important;
    min-width: 175px !important;
    max-width: 175px !important;
    background: #898989 !important;
}

.request-number-column {
    position: sticky;
    z-index: 6;
    left: 0;
    width: 175px !important;
    min-width: 175px !important;
    max-width: 175px !important;
    background: #ffffff !important;
}

.large-text-header,
.large-text-column {
    width: 280px !important;
    min-width: 280px !important;
    max-width: 280px !important;
}

.large-text-column {
    text-align: left !important;
}

.long-text-value {
    display: -webkit-box;
    overflow: hidden;
    line-height: 18px;
    text-overflow: ellipsis;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 4;
}

.status-header {
    position: sticky !important;
    z-index: 11 !important;
    right: 110px;
    width: 175px !important;
    min-width: 175px !important;
    max-width: 175px !important;
    background: #898989 !important;
}

.status-column {
    position: sticky;
    z-index: 7;
    right: 110px;
    width: 175px !important;
    min-width: 175px !important;
    max-width: 175px !important;
    background: #ffffff !important;
    vertical-align: middle !important;
}

.actions-header {
    position: sticky !important;
    z-index: 12 !important;
    right: 0;
    width: 110px !important;
    min-width: 110px !important;
    max-width: 110px !important;
    background: #818181 !important;
}

.actions-column {
    position: sticky;
    z-index: 8;
    right: 0;
    width: 110px !important;
    min-width: 110px !important;
    max-width: 110px !important;
    background: #ffffff !important;
    vertical-align: middle !important;
}


/* =====================================================
   Status Labels
   ===================================================== */

.status-label {
    display: inline-block;
    min-width: 110px;
    max-width: 155px;
    padding: 6px 10px;
    border-radius: 14px;
    font-size: 11px;
    font-weight: 600;
    text-align: center;
}

.status-draft {
    color: #495057;
    background: #e9ecef;
}

.status-submitted {
    color: #004085;
    background: #cce5ff;
}

.status-approval {
    color: #856404;
    background: #fff3cd;
}

.status-approved {
    color: #155724;
    background: #c3e6cb;
}

.status-progress {
    color: #0c5460;
    background: #d1ecf1;
}

.status-feedback {
    color: #663c00;
    background: #ffe5b4;
}

.status-complete {
    color: #155724;
    background: #d4edda;
}

.status-rejected {
    color: #721c24;
    background: #f8d7da;
}

.status-default {
    color: #383d41;
    background: #e2e3e5;
}


/* =====================================================
   View Action
   ===================================================== */

.record-actions {
    display: flex;
    min-height: 42px;
    align-items: center;
    justify-content: center;
}

.record-action-button {
    display: inline-flex;
    width: 38px;
    height: 38px;
    padding: 0;
    align-items: center;
    justify-content: center;
    background: transparent;
    border-radius: 3px;
    cursor: pointer;
    transition:
        color 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.view-button {
    color: #ed6b21;
    background: #ffffff;
    border: 1px solid transparent;
    font-size: 22px;
}

.view-button:hover,
.view-button:focus {
    color: #c94d08;
    background: #fff2ea;
    border-color: #ed6b21;
    outline: none;
}


/* =====================================================
   Back Button
   ===================================================== */

.records-back-section {
    padding: 9px 11px;
    background: #ffffff;
    border-top: 1px solid #eeeeee;
}

.records-back-button {
    display: inline-flex;
    width: 40px;
    height: 40px;
    padding: 0;
    align-items: center;
    justify-content: center;
    color: #111111;
    background: #ffffff;
    border: 3px solid #111111;
    border-radius: 50%;
    font-size: 22px;
    cursor: pointer;
}

.records-back-button:hover {
    color: #ffffff;
    background: #111111;
}


/* =====================================================
   Responsive
   ===================================================== */

@media screen and (max-width: 1000px) {

    .records-page-header {
        flex-wrap: wrap;
    }

    .records-title {
        width: 100%;
    }

    .logged-in-user-details {
        width: auto;
        flex: 1;
    }

    .filter-fields-container {
        grid-template-columns: 1fr;
    }
}

@media screen and (max-width: 650px) {

    .records-page-header {
        padding: 12px;
    }

    .records-title {
        font-size: 22px;
        line-height: 34px;
    }

    .logged-in-user-details {
        width: 100%;
        margin-right: 0;
    }

    .healthineers-logo {
        margin-top: 10px;
    }

    .records-filter-section {
        padding: 15px;
    }

    .filter-item {
        display: block;
    }

    .filter-item label {
        display: block;
        width: auto;
        margin-bottom: 5px;
        text-align: left;
    }

    .filter-buttons-row {
        flex-direction: column;
    }

    .filter-action-button {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    /* =====================================================
       Configuration
       ===================================================== */

    var TABLE =
        "x_1549902_asean_0_learning_application";

    var STATUS_FIELD =
        "u_status";


    /* =====================================================
       Initial Data
       ===================================================== */

    data.records = [];

    data.success = true;
    data.message = "";

    data.userEmail =
        gs.getUser().getEmail() || "";

    data.userName =
        gs.getUserDisplayName();

    data.userLevel =
        "Employee";

    data.tableName =
        TABLE;

    data.filterOptions = {
        requestNumbers: [],
        courseTypes: [],
        courseFormats: [],
        statuses: []
    };


    /* =====================================================
       Utility Functions
       ===================================================== */

    function getValue(
        gr,
        fieldName
    ) {

        if (
            !gr ||
            !gr.isValidField(fieldName)
        ) {
            return "";
        }

        return gr.getValue(
            fieldName
        ) || "";
    }


    function getDisplay(
        gr,
        fieldName
    ) {

        if (
            !gr ||
            !gr.isValidField(fieldName)
        ) {
            return "";
        }

        return gr.getDisplayValue(
            fieldName
        ) || "";
    }


    function addUnique(
        array,
        value
    ) {

        if (
            value &&
            array.indexOf(value) === -1
        ) {
            array.push(value);
        }
    }


    function addUniqueObject(
        array,
        value,
        displayValue
    ) {

        if (!value) {
            return;
        }

        for (
            var i = 0;
            i < array.length;
            i++
        ) {

            if (
                array[i].value === value
            ) {
                return;
            }
        }

        array.push({
            value: value,
            display:
                displayValue || value
        });
    }


    /* =====================================================
       Logged-in Employee Query
       ===================================================== */

    function addEmployeeQuery(gr) {

        /*
         * The logged-in user can see all their
         * application records regardless of status.
         */

        var employeeQuery =
            gr.addQuery(
                "u_employee_name",
                gs.getUserID()
            );

        if (data.userEmail) {

            employeeQuery.addOrCondition(
                "u_employee_email",
                data.userEmail
            );
        }
    }


    /* =====================================================
       Load Filter Options
       ===================================================== */

    function loadFilterOptions() {

        data.filterOptions = {
            requestNumbers: [],
            courseTypes: [],
            courseFormats: [],
            statuses: []
        };


        var gr =
            new GlideRecordSecure(
                TABLE
            );

        addEmployeeQuery(gr);

        gr.orderByDesc(
            "sys_created_on"
        );

        gr.query();


        while (gr.next()) {

            addUnique(
                data.filterOptions
                    .requestNumbers,
                getDisplay(
                    gr,
                    "number"
                )
            );


            addUniqueObject(
                data.filterOptions
                    .courseTypes,
                getValue(
                    gr,
                    "u_course_type"
                ),
                getDisplay(
                    gr,
                    "u_course_type"
                )
            );


            addUniqueObject(
                data.filterOptions
                    .courseFormats,
                getValue(
                    gr,
                    "u_course_format"
                ),
                getDisplay(
                    gr,
                    "u_course_format"
                )
            );


            addUniqueObject(
                data.filterOptions
                    .statuses,
                getValue(
                    gr,
                    STATUS_FIELD
                ),
                getDisplay(
                    gr,
                    STATUS_FIELD
                )
            );
        }


        data.filterOptions
            .requestNumbers
            .sort();


        data.filterOptions
            .courseTypes
            .sort(function(a, b) {

                return String(
                    a.display
                ).localeCompare(
                    String(
                        b.display
                    )
                );
            });


        data.filterOptions
            .courseFormats
            .sort(function(a, b) {

                return String(
                    a.display
                ).localeCompare(
                    String(
                        b.display
                    )
                );
            });


        data.filterOptions
            .statuses
            .sort(function(a, b) {

                return String(
                    a.display
                ).localeCompare(
                    String(
                        b.display
                    )
                );
            });
    }


    /* =====================================================
       Load Records
       ===================================================== */

    function loadRecords(filters) {

        filters = filters || {};

        var records = [];

        var gr =
            new GlideRecordSecure(
                TABLE
            );


        /*
         * No status restriction is added here.
         * This means all statuses are displayed.
         */
        addEmployeeQuery(gr);


        /* Request Number Filter */
        if (filters.requestNumber) {

            var requestNumber =
                String(
                    filters.requestNumber
                ).trim();

            if (requestNumber) {

                gr.addQuery(
                    "number",
                    "CONTAINS",
                    requestNumber
                );
            }
        }


        /* Course Type Filter */
        if (filters.courseType) {

            gr.addQuery(
                "u_course_type",
                filters.courseType
            );
        }


        /* Course Format Filter */
        if (filters.courseFormat) {

            gr.addQuery(
                "u_course_format",
                filters.courseFormat
            );
        }


        /* Optional Status Filter */
        if (filters.status) {

            gr.addQuery(
                STATUS_FIELD,
                filters.status
            );
        }


        gr.orderByDesc(
            "sys_created_on"
        );

        gr.query();


        while (gr.next()) {

            var statusValue =
                getValue(
                    gr,
                    STATUS_FIELD
                );


            records.push({

                sys_id:
                    gr.getUniqueValue(),

                requestNumber:
                    getDisplay(
                        gr,
                        "number"
                    ),

                employeeName:
                    getDisplay(
                        gr,
                        "u_employee_name"
                    ),

                employeeEmail:
                    getValue(
                        gr,
                        "u_employee_email"
                    ),

                country:
                    getDisplay(
                        gr,
                        "u_country"
                    ),

                manager:
                    getDisplay(
                        gr,
                        "u_manager_email"
                    ),

                managementL2:
                    getDisplay(
                        gr,
                        "u_management_l2"
                    ),

                managerL2Required:
                    getDisplay(
                        gr,
                        "manager_approval_l2_required"
                    ),

                courseTitle:
                    getDisplay(
                        gr,
                        "u_course_title"
                    ),

                courseType:
                    getDisplay(
                        gr,
                        "u_course_type"
                    ),

                courseFormat:
                    getDisplay(
                        gr,
                        "u_course_format"
                    ),

                courseStartDate:
                    getDisplay(
                        gr,
                        "course_start_date"
                    ),

                courseEndDate:
                    getDisplay(
                        gr,
                        "u_course_end_date"
                    ),

                totalTrainingHours:
                    getDisplay(
                        gr,
                        "u_total_training_hours"
                    ),

                trainingCountry:
                    getDisplay(
                        gr,
                        "u_training_country"
                    ),

                trainingProvider:
                    getDisplay(
                        gr,
                        "u_training_provider_name"
                    ),

                paymentRequired:
                    getDisplay(
                        gr,
                        "is_payment_required"
                    ),

                courseFee:
                    getDisplay(
                        gr,
                        "u_course_fee"
                    ),

                otherExpenses:
                    getDisplay(
                        gr,
                        "u_other_expenses"
                    ),

                specifyOtherExpenses:
                    getDisplay(
                        gr,
                        "u_specify_other_expenses"
                    ),

                totalCost:
                    getDisplay(
                        gr,
                        "u_total_cost"
                    ),

                currency:
                    getDisplay(
                        gr,
                        "currency"
                    ),

                comment:
                    getValue(
                        gr,
                        "u_comment"
                    ),

                approval:
                    getDisplay(
                        gr,
                        "approval"
                    ),

                openedAt:
                    getDisplay(
                        gr,
                        "opened_at"
                    ),

                status:
                    getDisplay(
                        gr,
                        STATUS_FIELD
                    ),

                statusValue:
                    statusValue
            });
        }

        return records;
    }


    /* =====================================================
       Client Actions
       ===================================================== */

    if (
        input &&
        input.action === "search"
    ) {

        data.records =
            loadRecords(
                input.filters || {}
            );

        data.success = true;

        return;
    }


    if (
        input &&
        input.action === "refresh"
    ) {

        loadFilterOptions();

        data.records =
            loadRecords(
                input.filters || {}
            );

        data.success = true;

        return;
    }


    if (
        input &&
        input.action === "reset"
    ) {

        loadFilterOptions();

        data.records =
            loadRecords({});

        data.success = true;

        return;
    }


    /* =====================================================
       Initial Widget Load
       ===================================================== */

    loadFilterOptions();

    data.records =
        loadRecords({});

})();
